import * as T from './three.js';
export const CRATE_ITEMS=[{wire:2,cells:2},{electronics:2,steel:2},{wire:2,electronics:2},{cells:3,steel:2}];
export function validateCrateContents(r){if(r.crateContents===undefined)r.crateContents=CRATE_ITEMS.map((c,i)=>r.crates[i]?{}:{...c});if(!Array.isArray(r.crateContents)||r.crateContents.length!==4)throw Error('Invalid salvage record');r.crateContents.forEach((c,i)=>{if(!c||typeof c!=='object'||Array.isArray(c))throw Error('Invalid salvage contents');for(const [id,n]of Object.entries(c))if(!Object.hasOwn(CRATE_ITEMS[i],id)||!Number.isInteger(n)||n<0||n>CRATE_ITEMS[i][id])throw Error('Invalid salvage quantity');if(r.crates[i]&&Object.values(c).some(n=>n>0))throw Error('Empty crate contains items');r.crates[i]=!Object.values(c).some(n=>n>0);});return r.crateContents;}
export function randomEnvironment(settings,rng=Math.random){if(!settings.randomEnvironment)return;settings.sunHour=Math.floor(rng()*240)/10;settings.weather=['dusk','dusk','heat','rain','storm','sandstorm'][Math.min(5,Math.floor(rng()*6))];}
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function lootWindow(items,name,weight,limit,icon,definitions,notice=''){const rows=Object.entries(items).filter(([,n])=>n>0);return `<article class="lootWindow"><span class="eyebrow">CONTAINER OPEN / SELECT CONTENTS</span><h2>${esc(name)}</h2><p>Pack ${weight.toFixed(1)} / ${limit} kg · Untaken items remain in this box.</p><div class="lootRows">${rows.map(([id,n])=>`<button data-loot="${id}" aria-label="Take one ${esc(definitions[id].name)}">${icon(id)}<span><b>${esc(definitions[id].name)}</b><small>${definitions[id].mass} kg each · Click to take one</small></span><strong>×${n}</strong><span>＋</span></button>`).join('')||'<p class="emptyLoot">Container empty.</p>'}</div><p role="status">${esc(notice)}</p><div class="lootActions"><button data-panel="play">CLOSE</button><button class="primary" data-loot="all" ${rows.length?'':'disabled'}>TAKE WHAT FITS</button></div></article>`;}
export class Guidance{
 constructor(scene){this.rings=[];this.glows=new Map();for(const color of [0x65ffe0,0xffd984]){const g=new T.Group(),m=new T.MeshBasicMaterial({color,transparent:true,opacity:.8,depthWrite:false,toneMapped:false});const ring=new T.Mesh(new T.TorusGeometry(2.3,.045,6,64),m);ring.rotation.x=Math.PI/2;g.add(ring);const pillar=new T.Mesh(new T.CylinderGeometry(.035,.035,3,6),m);pillar.position.y=1.5;g.add(pillar);g.visible=false;scene.add(g);this.rings.push(g);}}
 glow(root,on,now){if(!this.glows.has(root)){const materials=[];root.traverse(o=>{if(!o.isMesh)return;const copy=m=>{if(!m.emissive)return m;const c=m.clone();c.onBeforeCompile=m.onBeforeCompile;c.customProgramCacheKey=m.customProgramCacheKey;materials.push({m:c,color:c.emissive.clone(),intensity:c.emissiveIntensity});return c;};o.material=Array.isArray(o.material)?o.material.map(copy):copy(o.material);});this.glows.set(root,materials);}for(const r of this.glows.get(root)){r.m.emissive.copy(on?new T.Color(0x4cf5d0):r.color);r.m.emissiveIntensity=on?.45+Math.sin(now*.003)*.2:r.intensity;}}
 update(s,started,screen,page,camera,bike,trailer,crate,now){const intro=started&&s.leg<=1&&s.intro.stage!=='line';this.glow(bike,intro&&!s.intro.mounted,now);this.glow(crate.mesh,intro&&s.intro.mounted&&!s.intro.salvaged,now);for(const [i,g]of this.rings.entries()){g.visible=intro&&(i?s.intro.mounted&&!s.intro.salvaged:!s.intro.mounted);g.position.copy(i?crate.mesh.position:bike.position);g.position.y+=.12;g.children[0].scale.setScalar(1+Math.sin(now*.003)*.055);g.children.forEach(o=>o.material.opacity=.55+Math.sin(now*.004)*.25);}if(screen==='bikeintro'&&document.body.classList.contains('menu-open')){const target=page?trailer.position:bike.position;bike.visible=true;camera.children.forEach(o=>o.visible=false);const a=now*.0001;camera.position.set(target.x+Math.cos(a)*5.5,target.y+3,target.z+Math.sin(a)*5.5);camera.lookAt(target.x,target.y+1,target.z);camera.updateMatrixWorld();}}
}
